  maintenance: { label: "Maintenance expense", category: "Financial", definition: "Cost of maintaining aircraft, engines and related flight equipment.", formula: "Reported maintenance expense", source: "BTS Form 41 Schedule P-1.2" },
  passenger_service: { label: "Passenger service expense", category: "Financial", definition: "Costs of passenger handling and onboard/customer service activities.", formula: "Reported passenger service expense", source: "BTS Form 41 Schedule P-1.2" },
  depreciation: { label: "Depreciation and amortization", category: "Financial", definition: "Non-cash recognition of the cost of aircraft and other long-lived assets over their useful lives.", formula: "Reported D&A expense", source: "BTS Form 41 Schedule P-1.2" },
  passengers: { label: "Passengers", category: "Network", definition: "Passengers transported on reported flight segments in the selected network scope.", formula: "Sum of T-100 segment passengers", source: "BTS T-100 domestic and T-100 international" },
