  rpm: { label: "RPM", category: "Network", definition: "Revenue Passenger Miles. Demand adjusted for distance: one paying passenger flown one mile equals one RPM.", formula: "Passengers x segment distance", source: "Calculated from BTS T-100" },
  asm: { label: "ASM", category: "Network", definition: "Available Seat Miles. Capacity adjusted for distance: one seat offered for one mile equals one ASM.", formula: "Available seats x segment distance", source: "Calculated from BTS T-100" },
  load_factor: { label: "Load factor", category: "Network", definition: "Distance-weighted utilization of seat capacity. Higher is usually better, but extremely high load factors can limit growth and resilience.", formula: "RPM / ASM", source: "Calculated from BTS T-100" },
  seat_load_factor: { label: "Seat load factor", category: "Network", definition: "Simple passenger-to-seat utilization without weighting by route distance.", formula: "Passengers / Available seats", source: "Calculated from BTS T-100" },
