const esc = (v) => String(v ?? "").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const n = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
const pctChange = (c,p) => Number.isFinite(c)&&Number.isFinite(p)&&p!==0 ? (c/p-1)*100 : null;
const ratio = (a,b) => b ? a/b : null;
const sum = (items,key) => items.reduce((a,x)=>a+n(x[key]),0);
const deltaTone = (v,favorablePositive=true) => !Number.isFinite(v)||Math.abs(v)<1e-10 ? "neutral" : ((favorablePositive ? v>0 : v<0) ? "positive" : "negative");
const fmtPct = (v,d=1,sign=true) => v==null||!Number.isFinite(v) ? "n/a" : `${sign&&v>0?"+":""}${v.toFixed(d)}%`;
const fmtPp = (v,d=1) => v==null||!Number.isFinite(v) ? "n/a" : `${v>0?"+":""}${v.toFixed(d)}pp`;
const fmtUsdM = (v,d=0) => v==null||!Number.isFinite(v) ? "n/a" : `${v<0?"-":""}$${Math.abs(v).toLocaleString(undefined,{maximumFractionDigits:d})}m`;
const fmtUsdBn = (v,d=2) => v==null||!Number.isFinite(v) ? "n/a" : `${v<0?"-":""}$${(Math.abs(v)/1000).toFixed(d)}bn`;
const fmtUsd = (v,d=2) => v==null||!Number.isFinite(v) ? "n/a" : `$${v.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d})}`;
const fmtInt = (v) => v==null||!Number.isFinite(v) ? "n/a" : Math.round(v).toLocaleString();
function fmtCompact(v,d=1){ if(v==null||!Number.isFinite(v))return"n/a"; const a=Math.abs(v); if(a>=1e12)return`${(v/1e12).toFixed(d)}tn`; if(a>=1e9)return`${(v/1e9).toFixed(d)}bn`; if(a>=1e6)return`${(v/1e6).toFixed(d)}m`; if(a>=1e3)return`${(v/1e3).toFixed(d)}k`; return v.toLocaleString(undefined,{maximumFractionDigits:d}); }
function cleanManufacturer(v){const s=String(v||"").toLowerCase();if(s.includes("boeing"))return"Boeing";if(s.includes("airbus"))return"Airbus";if(s.includes("bombard"))return"Bombardier";if(s.includes("embraer"))return"Embraer";return String(v||"Unknown").replace(/company|industries/ig,"").trim();}

function metricHelp(key){ const m=METRICS[key]; if(!m)return""; const text=`${m.definition} Formula: ${m.formula}. Source: ${m.source}.`; return `<span class="metric-help" tabindex="0" aria-label="Explain ${esc(m.label)}" data-tooltip="${esc(text)}">?</span>`; }
function metricTitle(key,label=null){ const m=METRICS[key]; return `<span class="metric-title">${esc(label||m?.label||key)} ${metricHelp(key)}</span>`; }
function sourceChip(kind){
  const map={finance:["BTS quarterly P&L","Schedule P-1.2: quarterly airline income statement"],aircraft:["BTS aircraft economics","Schedule P-5.2: cost and air hours by aircraft type"],fuel:["BTS monthly fuel","Schedule P-12(a): monthly fuel cost and gallons"],network:["BTS network","T-100 domestic + T-100-I international traffic and capacity"],fleet:["BTS fleet inventory","Schedule B-43: annual tail-level aircraft inventory"]};
  const [label,tip]=map[kind]||[kind,kind]; return `<span class="data-pill live" data-tooltip="${esc(tip)}">${esc(label)}</span>`;
}

function destroyCharts(){ charts.forEach(c=>{try{c.destroy();}catch(_){}}); charts=[]; }
function chartAvailable(){return typeof window.Chart!=="undefined";}
function makeChart(id,config){const canvas=document.getElementById(id);if(!canvas)return null;if(!chartAvailable()){canvas.parentElement.innerHTML='<div class="chart-empty">Charts could not load. The analytical tables and comments remain available.</div>';return null;} const c=new Chart(canvas,config);charts.push(c);return c;}
function commonChartOptions(extra={}){return{responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:"rgba(29,29,31,.94)",padding:10,cornerRadius:10}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:9}}},y:{grid:{color:"rgba(29,29,31,.06)"},border:{display:false},ticks:{font:{size:9}}}},...extra};}

function parseQuarter(p){const m=/^(\d{4})-Q([1-4])$/.exec(String(p));return m?{year:+m[1],q:+m[2]}:null;}
function parseMonth(p){const m=/^(\d{4})-(\d{2})$/.exec(String(p));return m?{year:+m[1],month:+m[2]}:null;}
function periodByExact(data,period){return data.find(x=>x.period===period)||null;}
function previousRow(data,index){return index>0?data[index-1]:null;}
function quarterLastYear(data,row){const x=parseQuarter(row?.period);return x?periodByExact(data,`${x.year-1}-Q${x.q}`):null;}
function monthLastYear(data,row){const x=parseMonth(row?.period);return x?periodByExact(data,`${x.year-1}-${String(x.month).padStart(2,"0")}`):null;}

const FIN_KEYS=["operating_revenue_usd_m","operating_expense_usd_m","operating_profit_loss_usd_m","passenger_revenue_usd_m","flying_operations_expense_usd_m","maintenance_expense_usd_m","passenger_service_expense_usd_m","depreciation_amortization_usd_m"];
function aggregateFinancialYTD(data,row){const x=parseQuarter(row?.period);if(!x)return null;const rows=data.filter(r=>{const p=parseQuarter(r.period);return p&&p.year===x.year&&p.q<=x.q;});if(!rows.length)return null;const out={period:`${x.year} YTD Q${x.q}`,raw_period:row.period};FIN_KEYS.forEach(k=>out[k]=sum(rows,k));out.operating_margin=ratio(out.operating_profit_loss_usd_m,out.operating_revenue_usd_m);return out;}
function financialContext(){const data=bts?.p12_financials||[];if(!data.length)return{data,current:null,prior:null};let idx=state.financialPeriod?data.findIndex(d=>d.period===state.financialPeriod):data.length-1;if(idx<0)idx=data.length-1;let raw=data[idx],priorRaw=null,current=raw,prior=null;
  if(state.compare==="prior"){priorRaw=previousRow(data,idx);prior=priorRaw;}
  else if(state.compare==="ytd"){current=aggregateFinancialYTD(data,raw);const q=parseQuarter(raw.period);const match=q?periodByExact(data,`${q.year-1}-Q${q.q}`):null;prior=match?aggregateFinancialYTD(data,match):null;priorRaw=match;}
  else{priorRaw=quarterLastYear(data,raw);prior=priorRaw;}
  if(!prior){for(let i=data.length-1;i>=0;i--){raw=data[i];if(state.compare==="prior")priorRaw=previousRow(data,i);else if(state.compare==="ytd"){const q=parseQuarter(raw.period);priorRaw=q?periodByExact(data,`${q.year-1}-Q${q.q}`):null;}else priorRaw=quarterLastYear(data,raw);if(priorRaw){idx=i;current=state.compare==="ytd"?aggregateFinancialYTD(data,raw):raw;prior=state.compare==="ytd"?aggregateFinancialYTD(data,priorRaw):priorRaw;break;}}}
  return{data,current,prior,raw,index:idx};}

function scopedNetworkRow(row){if(!row)return null;if(state.scope==="all")return{...row};const s=row.scope?.[state.scope];if(!s)return{period:row.period,passengers:0,available_seats:0,departures_performed:0,air_time_minutes:0,rpm:0,asm:0,load_factor:null,seat_load_factor:null};const out={period:row.period,...s};out.load_factor=ratio(n(out.rpm),n(out.asm));out.seat_load_factor=ratio(n(out.passengers),n(out.available_seats));return out;}
function aggregateMonthlyYTD(data,row){const x=parseMonth(row?.period);if(!x)return null;const rows=data.filter(r=>{const p=parseMonth(r.period);return p&&p.year===x.year&&p.month<=x.month;});if(!rows.length)return null;const out={period:`${x.year} YTD ${String(x.month).padStart(2,"0")}`,raw_period:row.period};["passengers","available_seats","departures_performed","air_time_minutes","rpm","asm"].forEach(k=>out[k]=sum(rows,k));out.load_factor=ratio(out.rpm,out.asm);out.seat_load_factor=ratio(out.passengers,out.available_seats);return out;}
function networkContext(){const full=(bts?.t100_network?.history||[]).map(scopedNetworkRow);const visible=full.slice(-Math.min(state.range,full.length));if(!full.length)return{full,visible,current:null,prior:null};let row=state.networkPeriod?periodByExact(full,state.networkPeriod):full.at(-1);if(!row)row=full.at(-1);const idx=full.findIndex(d=>d.period===row.period);let current=row,prior=null;if(state.compare==="prior")prior=previousRow(full,idx);else if(state.compare==="ytd"){current=aggregateMonthlyYTD(full,row);const p=parseMonth(row.period);const match=p?periodByExact(full,`${p.year-1}-${String(p.month).padStart(2,"0")}`):null;prior=match?aggregateMonthlyYTD(full,match):null;}else prior=monthLastYear(full,row);return{full,visible,current,prior,raw:row};}

function scopedFuelRow(row){if(!row)return null;if(state.scope==="all")return{...row};const prefix=state.scope==="domestic"?"domestic":"international";const gallons=n(row[`${prefix}_fuel_gallons`]);const cost=n(row[`${prefix}_fuel_cost_usd`]);return{period:row.period,fuel_gallons:gallons,fuel_cost_usd:cost,fuel_cost_per_gallon_usd:ratio(cost,gallons),domestic_fuel_gallons:n(row.domestic_fuel_gallons),international_fuel_gallons:n(row.international_fuel_gallons)};}
function aggregateFuelYTD(data,row){const x=parseMonth(row?.period);if(!x)return null;const rows=data.filter(r=>{const p=parseMonth(r.period);return p&&p.year===x.year&&p.month<=x.month;});if(!rows.length)return null;const out={period:`${x.year} YTD ${String(x.month).padStart(2,"0")}`,raw_period:row.period,fuel_gallons:sum(rows,"fuel_gallons"),fuel_cost_usd:sum(rows,"fuel_cost_usd")};out.fuel_cost_per_gallon_usd=ratio(out.fuel_cost_usd,out.fuel_gallons);return out;}
function fuelContext(){const full=(bts?.p12a_fuel||[]).map(scopedFuelRow);const visible=full.slice(-Math.min(state.range,full.length));if(!full.length)return{full,visible,current:null,prior:null};let row=state.fuelPeriod?periodByExact(full,state.fuelPeriod):full.at(-1);if(!row)row=full.at(-1);const idx=full.findIndex(d=>d.period===row.period);let current=row,prior=null;if(state.compare==="prior")prior=previousRow(full,idx);else if(state.compare==="ytd"){current=aggregateFuelYTD(full,row);const p=parseMonth(row.period);const match=p?periodByExact(full,`${p.year-1}-${String(p.month).padStart(2,"0")}`):null;prior=match?aggregateFuelYTD(full,match):null;}else prior=monthLastYear(full,row);return{full,visible,current,prior,raw:row};}

function compareLabel(cadence){if(state.compare==="prior")return cadence==="quarterly"?"prior quarter":"prior month";if(state.compare==="ytd")return"prior-year YTD";return"year ago";}
function compareModeLabel(){return state.compare==="ytd"?"YTD vs prior YTD":state.compare==="prior"?"prior period":"year over year";}

function largestFinancialDrivers(c,p){const lines=[
  ["Flying operations","flying_operations_expense_usd_m"],["Maintenance","maintenance_expense_usd_m"],["Passenger service","passenger_service_expense_usd_m"],["Depreciation and amortization","depreciation_amortization_usd_m"]
].map(([label,key])=>({label,key,delta:n(c?.[key])-n(p?.[key])})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));return lines;}
function financialMetricComment(key,c,p){if(!c||!p)return"No valid comparator is available for this period.";const revD=n(c.operating_revenue_usd_m)-n(p.operating_revenue_usd_m);const opexD=n(c.operating_expense_usd_m)-n(p.operating_expense_usd_m);const profitD=n(c.operating_profit_loss_usd_m)-n(p.operating_profit_loss_usd_m);const revG=pctChange(n(c.operating_revenue_usd_m),n(p.operating_revenue_usd_m));const opexG=pctChange(n(c.operating_expense_usd_m),n(p.operating_expense_usd_m));const marginD=(n(c.operating_margin)-n(p.operating_margin))*100;const drivers=largestFinancialDrivers(c,p);const top=drivers[0];
  if(key==="operating_revenue_usd_m"){const paxD=n(c.passenger_revenue_usd_m)-n(p.passenger_revenue_usd_m);const share=revD?Math.abs(paxD/revD)*100:null;return `Revenue changed ${fmtUsdM(revD)} (${fmtPct(revG)}). Passenger revenue contributed ${fmtUsdM(paxD)}${share!=null?` or about ${share.toFixed(0)}% of the net revenue movement`:""}. Operating profit ${profitD>=0?"improved":"fell"} ${fmtUsdM(Math.abs(profitD))}, so revenue growth did ${profitD>=0?"":"not "}fully translate into profit.`;}
  if(key==="operating_expense_usd_m"){const gap=(opexG??0)-(revG??0);const share=opexD?Math.abs(top.delta/opexD)*100:null;return `Operating expense changed ${fmtUsdM(opexD)} (${fmtPct(opexG)}), ${gap>=0?`${gap.toFixed(1)}pp faster than revenue`:`${Math.abs(gap).toFixed(1)}pp slower than revenue`}. ${top.label} was the largest tracked cost movement at ${fmtUsdM(top.delta)}${share!=null?` (${share.toFixed(0)}% of the net OPEX change)`:""}.`;} 
  if(key==="operating_profit_loss_usd_m")return `Operating profit changed ${fmtUsdM(profitD)} because revenue contributed ${fmtUsdM(revD)} while operating expense absorbed ${fmtUsdM(opexD)}. The resulting operating-margin movement was ${fmtPp(marginD)}.`;
  if(key==="passenger_revenue_usd_m"){const d=n(c.passenger_revenue_usd_m)-n(p.passenger_revenue_usd_m);const currentShare=ratio(n(c.passenger_revenue_usd_m),n(c.operating_revenue_usd_m));return `Passenger revenue changed ${fmtUsdM(d)} (${fmtPct(pctChange(n(c.passenger_revenue_usd_m),n(p.passenger_revenue_usd_m)))}). It represents ${(n(currentShare)*100).toFixed(1)}% of current operating revenue, making it the main revenue engine.`;}
  const map={flying_operations_expense_usd_m:"Flying operations",maintenance_expense_usd_m:"Maintenance",passenger_service_expense_usd_m:"Passenger service",depreciation_amortization_usd_m:"Depreciation and amortization"};if(map[key]){const d=n(c[key])-n(p[key]);const share=opexD?Math.abs(d/opexD)*100:null;return `${map[key]} changed ${fmtUsdM(d)} (${fmtPct(pctChange(n(c[key]),n(p[key])))}). ${share!=null?`It explains roughly ${share.toFixed(0)}% of the net operating-expense movement.`:""} Revenue changed ${fmtPct(revG)}, so this cost line ${pctChange(n(c[key]),n(p[key]))>(revG??0)?"grew faster than revenue and pressured margin":"did not outpace revenue in this comparison"}.`;}
  return `The selected metric changed between ${p.period} and ${c.period}; no unsupported causal claim is added.`;
}

function financialCommentary(c,p){if(!c||!p)return{headline:"No valid financial comparator",body:"Choose a later quarter or another comparison mode.",bullets:[]};const revG=pctChange(n(c.operating_revenue_usd_m),n(p.operating_revenue_usd_m));const opexG=pctChange(n(c.operating_expense_usd_m),n(p.operating_expense_usd_m));const marginD=(n(c.operating_margin)-n(p.operating_margin))*100;const top=largestFinancialDrivers(c,p)[0];return{headline:marginD<-1?"Costs are taking a larger share of revenue":marginD>1?"Revenue is converting into profit more efficiently":"Margin is broadly stable",body:`Revenue changed ${fmtPct(revG)} while operating expense changed ${fmtPct(opexG)}. Operating margin moved ${fmtPp(marginD)}. ${top.label} is the largest tracked cost movement at ${fmtUsdM(top.delta)}.`,bullets:[financialMetricComment("operating_profit_loss_usd_m",c,p),`Comparison basis: ${compareModeLabel()}.`]};}
function networkCommentary(c,p){if(!c||!p)return{headline:"No valid network comparator",body:"The selected month does not have enough retained history for this comparison.",bullets:[]};const paxG=pctChange(n(c.passengers),n(p.passengers));const asmG=pctChange(n(c.asm),n(p.asm));const lfD=(n(c.load_factor)-n(p.load_factor))*100;const spread=(paxG??0)-(asmG??0);const scope=state.scope==="all"?"total network":`${state.scope} network`;return{headline:spread<-2?"Capacity is running ahead of passenger growth":spread>2?"Passenger growth is outpacing capacity":"Demand and capacity are broadly aligned",body:`In the ${scope}, passengers changed ${fmtPct(paxG)} and ASM changed ${fmtPct(asmG)}. Distance-weighted load factor moved ${fmtPp(lfD)}.`,bullets:[`RPM changed ${fmtPct(pctChange(n(c.rpm),n(p.rpm)))}.`,`All route and network messages are using the active ${state.scope} filter.`]};}
function fuelCommentary(c,p){if(!c||!p)return{headline:"No valid fuel comparator",body:"The selected month does not have enough retained history.",bullets:[]};const costD=n(c.fuel_cost_usd)-n(p.fuel_cost_usd);const gallonsD=n(c.fuel_gallons)-n(p.fuel_gallons);const priceD=n(c.fuel_cost_per_gallon_usd)-n(p.fuel_cost_per_gallon_usd);const priceEffect=priceD*n(c.fuel_gallons);const volumeEffect=gallonsD*n(p.fuel_cost_per_gallon_usd);const dominant=Math.abs(priceEffect)>=Math.abs(volumeEffect)?"price":"volume";return{headline:`Fuel ${dominant} is the larger modeled driver`,body:`Fuel cost changed ${fmtUsdM(costD/1e6)} in the ${state.scope} scope. Average cost per gallon changed ${fmtPct(pctChange(n(c.fuel_cost_per_gallon_usd),n(p.fuel_cost_per_gallon_usd)))} and gallons changed ${fmtPct(pctChange(n(c.fuel_gallons),n(p.fuel_gallons)))}.`,bullets:[`Approximate price effect: ${fmtUsdM(priceEffect/1e6)}.`,`Approximate volume effect: ${fmtUsdM(volumeEffect/1e6)}.`]};}

function latestIR(){if(!actuals)return null;const f=actuals.financials_usd_millions;const s=actuals.statistics;const marginC=100*n(f.operating_income.current)/n(f.operating_revenue.current);const marginP=100*n(f.operating_income.prior)/n(f.operating_revenue.prior);return{revG:pctChange(n(f.operating_revenue.current),n(f.operating_revenue.prior)),opexG:pctChange(n(f.operating_expense.current),n(f.operating_expense.prior)),profitG:pctChange(n(f.operating_income.current),n(f.operating_income.prior)),margin:marginC,marginD:marginC-marginP,fuelPriceG:pctChange(n(s.fuel_price_per_gallon.current),n(s.fuel_price_per_gallon.prior)),loadFactorD:n(s.load_factor_pct.current)-n(s.load_factor_pct.prior),casmG:pctChange(n(s.casm_cents.current),n(s.casm_cents.prior)),trasmG:pctChange(n(s.trasm_cents.current),n(s.trasm_cents.prior))};}
function controlAssessment(fin,net,fuel){const ir=latestIR();let risk=0;const reasons=[];const positives=[];const marginD=ir?.marginD ?? ((n(fin?.current?.operating_margin)-n(fin?.prior?.operating_margin))*100);const revG=ir?.revG ?? pctChange(n(fin?.current?.operating_revenue_usd_m),n(fin?.prior?.operating_revenue_usd_m));const opexG=ir?.opexG ?? pctChange(n(fin?.current?.operating_expense_usd_m),n(fin?.prior?.operating_expense_usd_m));const profitG=ir?.profitG ?? pctChange(n(fin?.current?.operating_profit_loss_usd_m),n(fin?.prior?.operating_profit_loss_usd_m));const paxG=pctChange(n(net?.current?.passengers),n(net?.prior?.passengers));const asmG=pctChange(n(net?.current?.asm),n(net?.prior?.asm));const lfD=(n(net?.current?.load_factor)-n(net?.prior?.load_factor))*100;const fuelPG=pctChange(n(fuel?.current?.fuel_cost_per_gallon_usd),n(fuel?.prior?.fuel_cost_per_gallon_usd));
  if(marginD<=-4){risk+=3;reasons.push(`Operating margin compressed ${Math.abs(marginD).toFixed(1)}pp.`);}else if(marginD<=-2){risk+=2;reasons.push(`Operating margin compressed ${Math.abs(marginD).toFixed(1)}pp.`);}else if(marginD<-.5){risk+=1;reasons.push(`Operating margin is modestly lower by ${Math.abs(marginD).toFixed(1)}pp.`);}else positives.push(`Operating margin is stable or improving (${fmtPp(marginD)}).`);
  const costGap=(opexG??0)-(revG??0);if(costGap>5){risk+=2;reasons.push(`Operating expense is growing ${costGap.toFixed(1)}pp faster than revenue.`);}else if(costGap>2){risk+=1;reasons.push(`Costs are growing faster than revenue by ${costGap.toFixed(1)}pp.`);}else positives.push("Revenue and operating-cost growth are reasonably aligned.");
  if(profitG!=null&&profitG<-20){risk+=2;reasons.push(`Operating profit is down ${Math.abs(profitG).toFixed(1)}%.`);}else if(profitG!=null&&profitG<0){risk+=1;reasons.push(`Operating profit is down ${Math.abs(profitG).toFixed(1)}%.`);}else positives.push("Operating profit is not deteriorating in the selected comparison.");
  const demandGap=(paxG??0)-(asmG??0);if(demandGap<-3){risk+=1;reasons.push(`${state.scope} passenger growth is trailing capacity by ${Math.abs(demandGap).toFixed(1)}pp.`);}else positives.push(`${state.scope} demand is broadly keeping pace with capacity.`);
  if(lfD<-2){risk+=1;reasons.push(`${state.scope} load factor is down ${Math.abs(lfD).toFixed(1)}pp.`);}else positives.push(`${state.scope} load factor is broadly stable (${fmtPp(lfD)}).`);
  if(fuelPG!=null&&fuelPG>20){risk+=1;reasons.push(`Fuel price is up ${fuelPG.toFixed(1)}%, a major external cost pressure.`);}else if(fuelPG!=null&&fuelPG<-10)positives.push(`Fuel price is providing a tailwind (${fmtPct(fuelPG)}).`);
  let status,label,tone,plain;if(risk>=7){status="critical";label="Critical";tone="critical";plain="Multiple core indicators are deteriorating at the same time. Management action would need to be immediate rather than incremental.";}else if(risk>=4){status="pressure";label="Under pressure";tone="pressure";plain="This is not a demand-collapse scenario, but cost and margin pressure are too large to call the situation fully controlled. The key question is how quickly cost growth normalizes.";}else if(risk>=2){status="watch";label="Watch";tone="watch";plain="Performance is still broadly controllable, but there are enough adverse signals that management should be watching the next periods closely.";}else{status="control";label="In control";tone="control";plain="The main financial and operating signals are broadly aligned. There is no evidence of a compounding deterioration in the current data.";}
  return{risk,status,label,tone,plain,reasons:reasons.slice(0,4),positives:positives.slice(0,3),metrics:{marginD,revG,opexG,profitG,paxG,asmG,lfD,fuelPG}};}

function kpiCard(metricKey,value,delta,note="",tone="neutral"){return`<article class="kpi-card"><div class="kpi-label">${metricTitle(metricKey)}</div><div class="kpi-value">${value}</div><div class="delta ${tone}">${delta}</div>${note?`<div class="kpi-note">${esc(note)}</div>`:""}</article>`;}
function insightCard(insight,kicker="Filter-aware commentary"){currentInsight=`${insight.headline}\n\n${insight.body}\n\n${(insight.bullets||[]).join("\n")}`;return`<article class="insight-card"><div class="insight-kicker">${esc(kicker)}</div><h2>${esc(insight.headline)}</h2><p>${esc(insight.body)}</p>${insight.bullets?.length?`<ul class="insight-list">${insight.bullets.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}</article>`;}
function scopeNotice(type){if(state.scope==="all")return"";if(type==="financial")return`<div class="notice scope-note">Network scope is set to <strong>${esc(state.scope)}</strong>. Form 41 P&L is airline-consolidated, so that filter does not change the financial statements. It does change network, fuel and overview operating commentary.</div>`;return"";}

function renderOverview(){const fin=financialContext(),net=networkContext(),fuel=fuelContext(),control=controlAssessment(fin,net,fuel),ir=latestIR();const latestFin=fin.current, latestNet=net.current, latestFuel=fuel.current;const latestActual=actuals?.financials_usd_millions;const stateClass=`control-${control.tone}`;
  dashboard.innerHTML=`
  <section class="control-hero ${stateClass}">
    <div><div class="control-eyebrow">Management control view</div><div class="control-status">${esc(control.label)}</div><p>${esc(control.plain)}</p><div class="control-score">Risk score ${control.risk}/10 <span>based on margin, cost growth, profit, demand/capacity, load factor and fuel pressure</span></div></div>
    <div class="control-signals"><h3>Why this status</h3>${control.reasons.length?control.reasons.map(x=>`<div class="signal bad">${esc(x)}</div>`).join(""):"<div class='signal good'>No material adverse signals cross the current thresholds.</div>"}${control.positives.map(x=>`<div class="signal good">${esc(x)}</div>`).join("")}</div>
  </section>
  <section class="kpi-grid">
    ${kpiCard("operating_margin",ir?`${ir.margin.toFixed(1)}%`:`${(n(latestFin?.operating_margin)*100).toFixed(1)}%`,ir?`${fmtPp(ir.marginD)} vs 2Q25`:fmtPp((n(latestFin?.operating_margin)-n(fin.prior?.operating_margin))*100),"Latest Delta management result",deltaTone(ir?.marginD??0))}
    ${kpiCard("operating_revenue",latestActual?fmtUsdBn(n(latestActual.operating_revenue.current)):fmtUsdBn(n(latestFin?.operating_revenue_usd_m)),ir?`${fmtPct(ir.revG)} vs 2Q25`:fmtPct(pctChange(n(latestFin?.operating_revenue_usd_m),n(fin.prior?.operating_revenue_usd_m))),"Latest Delta management result",deltaTone(ir?.revG??0))}
    ${kpiCard("load_factor",`${(n(latestNet?.load_factor)*100).toFixed(1)}%`,fmtPp((n(latestNet?.load_factor)-n(net.prior?.load_factor))*100),`${state.scope} · ${latestNet?.period||"n/a"}`,deltaTone(n(latestNet?.load_factor)-n(net.prior?.load_factor)))}
    ${kpiCard("fuel_price",fmtUsd(n(latestFuel?.fuel_cost_per_gallon_usd)),fmtPct(pctChange(n(latestFuel?.fuel_cost_per_gallon_usd),n(fuel.prior?.fuel_cost_per_gallon_usd))),`${state.scope} · ${latestFuel?.period||"n/a"}`,deltaTone(n(latestFuel?.fuel_cost_per_gallon_usd)-n(fuel.prior?.fuel_cost_per_gallon_usd),false))}
  </section>
  <section class="three-col control-detail-grid">
    <article class="panel"><div class="panel-header"><div><h2>Cost conversion</h2><p class="panel-subtitle">Can revenue growth absorb cost growth?</p></div></div><div class="big-signal ${(ir?.opexG??0)>(ir?.revG??0)?"negative":"positive"}">${fmtPct(ir?.opexG??0)}</div><p class="explain-copy">Operating expense growth versus ${fmtPct(ir?.revG??0)} revenue growth. The gap is ${((ir?.opexG??0)-(ir?.revG??0)).toFixed(1)}pp.</p></article>
    <article class="panel"><div class="panel-header"><div><h2>Demand versus capacity</h2><p class="panel-subtitle">Filtered to ${esc(state.scope)}</p></div></div><div class="big-signal">${fmtPct(pctChange(n(net.current?.passengers),n(net.prior?.passengers)))}</div><p class="explain-copy">Passengers versus ${fmtPct(pctChange(n(net.current?.asm),n(net.prior?.asm)))} ASM. ${esc(networkCommentary(net.current,net.prior).headline)}.</p></article>
    <article class="panel"><div class="panel-header"><div><h2>External pressure</h2><p class="panel-subtitle">Fuel cost per gallon</p></div></div><div class="big-signal ${deltaTone((fuel.current?.fuel_cost_per_gallon_usd||0)-(fuel.prior?.fuel_cost_per_gallon_usd||0),false)}">${fmtPct(pctChange(n(fuel.current?.fuel_cost_per_gallon_usd),n(fuel.prior?.fuel_cost_per_gallon_usd)))}</div><p class="explain-copy">Fuel price is largely external. The dashboard separates it from volume so management is not blamed for a commodity-price shock.</p></article>
  </section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Financial direction</h2><p class="panel-subtitle">Quarterly revenue and operating margin</p></div>${sourceChip("finance")}</div><div class="chart-shell"><canvas id="overview-fin"></canvas></div></article>${insightCard(financialCommentary(fin.current,fin.prior),"Financial diagnosis")}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Network direction</h2><p class="panel-subtitle">${esc(state.scope)} passengers and capacity</p></div>${sourceChip("network")}</div><div class="chart-shell"><canvas id="overview-net"></canvas></div></article>${insightCard(networkCommentary(net.current,net.prior),"Operating diagnosis")}</section>`;
  const f=bts?.p12_financials||[];makeChart("overview-fin",{type:"bar",data:{labels:f.map(x=>x.period),datasets:[{label:"Revenue $m",data:f.map(x=>x.operating_revenue_usd_m),backgroundColor:COLORS.blueSoft,borderRadius:7,yAxisID:"y"},{type:"line",label:"Margin %",data:f.map(x=>100*n(x.operating_margin)),borderColor:COLORS.dark,pointRadius:2,tension:.35,yAxisID:"y1"}]},options:commonChartOptions({plugins:{legend:{display:true,labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}},scales:{x:{grid:{display:false}},y:{grid:{color:COLORS.line},ticks:{callback:v=>`$${(v/1000).toFixed(0)}bn`}},y1:{position:"right",grid:{display:false},ticks:{callback:v=>`${v}%`}}}})});
  makeChart("overview-net",{type:"line",data:{labels:net.visible.map(x=>x.period),datasets:[{label:"Passengers",data:net.visible.map(x=>x.passengers),borderColor:COLORS.blue,backgroundColor:COLORS.fill,fill:true,tension:.35,pointRadius:1},{label:"ASM",data:net.visible.map(x=>x.asm),borderColor:COLORS.muted,borderDash:[4,4],tension:.35,pointRadius:0,yAxisID:"y1"}]},options:commonChartOptions({plugins:{legend:{display:true,labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}},scales:{x:{grid:{display:false}},y:{grid:{color:COLORS.line}},y1:{position:"right",grid:{display:false}}}})});
}

function financialRows(){return[["Operating revenue","operating_revenue_usd_m","operating_revenue",true],["Operating expense","operating_expense_usd_m","operating_expense",false],["Operating profit","operating_profit_loss_usd_m","operating_profit",true],["Passenger revenue","passenger_revenue_usd_m","passenger_revenue",true],["Flying operations","flying_operations_expense_usd_m","flying_operations",false],["Maintenance","maintenance_expense_usd_m","maintenance",false],["Passenger service","passenger_service_expense_usd_m","passenger_service",false],["Depreciation & amortization","depreciation_amortization_usd_m","depreciation",false]];}
function validFinancialPeriods(data){return data.filter((row,i)=>{if(state.compare==="prior")return i>0;if(state.compare==="ytd"){const q=parseQuarter(row.period);return q&&data.some(x=>x.period===`${q.year-1}-Q${q.q}`);}return Boolean(quarterLastYear(data,row));});}
function renderFinancials(){const ctx=financialContext();if(!ctx.current||!ctx.prior)return renderUnavailable("No valid financial comparison is available.");const c=ctx.current,p=ctx.prior,rows=financialRows();const marginD=(n(c.operating_margin)-n(p.operating_margin))*100;
  dashboard.innerHTML=`${scopeNotice("financial")}<section class="filter-context panel"><div class="panel-header"><div><h2>Financial period</h2><p class="panel-subtitle">YTD is recalculated from the quarterly data rather than copied from a source field.</p></div><select class="table-search" id="financial-period-select">${validFinancialPeriods(ctx.data).slice().reverse().map(x=>`<option value="${x.period}" ${x.period===ctx.raw?.period?"selected":""}>${x.period}</option>`).join("")}</select></div></section>
  <section class="kpi-grid">${kpiCard("operating_revenue",fmtUsdBn(n(c.operating_revenue_usd_m)),`${fmtPct(pctChange(n(c.operating_revenue_usd_m),n(p.operating_revenue_usd_m)))} vs ${p.period}`,c.period,deltaTone(n(c.operating_revenue_usd_m)-n(p.operating_revenue_usd_m)))}${kpiCard("operating_expense",fmtUsdBn(n(c.operating_expense_usd_m)),`${fmtPct(pctChange(n(c.operating_expense_usd_m),n(p.operating_expense_usd_m)))} vs ${p.period}`,c.period,deltaTone(n(c.operating_expense_usd_m)-n(p.operating_expense_usd_m),false))}${kpiCard("operating_profit",fmtUsdBn(n(c.operating_profit_loss_usd_m)),`${fmtPct(pctChange(n(c.operating_profit_loss_usd_m),n(p.operating_profit_loss_usd_m)))} vs ${p.period}`,c.period,deltaTone(n(c.operating_profit_loss_usd_m)-n(p.operating_profit_loss_usd_m)))}${kpiCard("operating_margin",`${(100*n(c.operating_margin)).toFixed(1)}%`,`${fmtPp(marginD)} vs ${p.period}`,c.period,deltaTone(marginD))}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Quarterly trend</h2><p class="panel-subtitle">The chart remains quarterly even when the selected comparison is YTD.</p></div>${sourceChip("finance")}</div><div class="chart-shell tall"><canvas id="fin-trend"></canvas></div></article>${insightCard(financialCommentary(c,p),"Financial variance analysis")}</section>
  <article class="panel flush"><div class="panel-header table-head"><div><h2>Variance table with analysis in the comment cell</h2><p class="panel-subtitle">No “go look elsewhere” language: each row quantifies the driver evidence available in Form 41.</p></div></div><div class="table-wrap"><table><thead><tr><th>Metric</th><th>${esc(c.period)}</th><th>${esc(p.period)}</th><th>Variance</th><th>Variance %</th><th class="comment-col">Analysis</th></tr></thead><tbody>${rows.map(([label,key,mkey,fav])=>{const cv=n(c[key]),pv=n(p[key]),d=cv-pv;return`<tr><td>${metricTitle(mkey,label)}</td><td>${fmtUsdM(cv)}</td><td>${fmtUsdM(pv)}</td><td class="${deltaTone(d,fav)}">${fmtUsdM(d)}</td><td class="${deltaTone(d,fav)}">${fmtPct(pctChange(cv,pv))}</td><td class="comment-analysis">${esc(financialMetricComment(key,c,p))}</td></tr>`;}).join("")}</tbody></table></div></article>`;
  const f=ctx.data;makeChart("fin-trend",{type:"bar",data:{labels:f.map(x=>x.period),datasets:[{label:"Revenue",data:f.map(x=>x.operating_revenue_usd_m),backgroundColor:"rgba(0,113,227,.20)",borderRadius:7},{label:"Expense",data:f.map(x=>x.operating_expense_usd_m),backgroundColor:"rgba(110,110,115,.15)",borderRadius:7},{type:"line",label:"Margin",data:f.map(x=>100*n(x.operating_margin)),borderColor:COLORS.dark,pointRadius:2,tension:.35,yAxisID:"y1"}]},options:commonChartOptions({plugins:{legend:{display:true,labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}},scales:{x:{grid:{display:false}},y:{grid:{color:COLORS.line},ticks:{callback:v=>`$${(v/1000).toFixed(0)}bn`}},y1:{position:"right",grid:{display:false},ticks:{callback:v=>`${v}%`}}}})});
  document.getElementById("financial-period-select")?.addEventListener("change",e=>{state.financialPeriod=e.target.value;render();});
}

function routeKey(r){return`${r.origin}-${r.destination}|${r.scope}`;}
function selectedRoutes(){const base=(bts?.t100_network?.top_directional_routes||[]).filter(r=>state.scope==="all"||r.scope===state.scope);const hist=bts?.t100_network?.route_history||{};return base.map(r=>{const rows=(hist[routeKey(r)]||[]).slice(-Math.min(state.range,(hist[routeKey(r)]||[]).length));if(!rows.length)return{...r};const o={...r,passengers:sum(rows,"passengers"),available_seats:sum(rows,"available_seats"),departures_performed:sum(rows,"departures_performed"),rpm:sum(rows,"rpm"),asm:sum(rows,"asm")};o.load_factor=ratio(o.rpm,o.asm);return o;}).sort((a,b)=>n(b.passengers)-n(a.passengers));}
function routeInsight(r){if(!r)return{headline:"No route available in this scope",body:state.scope==="international"?"International flying exists in T-100-I, but the current compact dataset does not yet contain a retained route ranking for it. The ETL has been updated to retain top routes separately by scope.":"No route matches the current filter.",bullets:[]};return{headline:`${r.origin} to ${r.destination}`,body:`${fmtCompact(n(r.passengers))} passengers and ${fmtInt(n(r.departures_performed))} performed departures in the selected ${state.range}-month window.`,bullets:[`Distance-weighted load factor: ${r.load_factor==null?"n/a":`${(100*r.load_factor).toFixed(1)}%`}.`,`Scope: ${r.scope}. Click selection now uses the exact plotted route index, not a label approximation.`]};}
function renderNetwork(){const ctx=networkContext();if(!ctx.current||!ctx.prior)return renderUnavailable("No valid network comparison is available.");const routes=selectedRoutes(),shown=routes.slice(0,12);let selected=routes.find(r=>routeKey(r)===state.selectedRouteKey)||shown[0]||null;if(selected&&!state.selectedRouteKey)state.selectedRouteKey=routeKey(selected);const lfD=(n(ctx.current.load_factor)-n(ctx.prior.load_factor))*100;const noIntl=state.scope==="international"&&routes.length===0;
  dashboard.innerHTML=`${noIntl?`<div class="notice warning-banner"><strong>International routes are temporarily missing from the compact ranking.</strong> Delta international traffic is present in T-100-I; the ETL has been corrected to retain top routes separately for Domestic and International and will repopulate this view on refresh.</div>`:""}<section class="filter-context panel"><div class="panel-header"><div><h2>Selected network month</h2><p class="panel-subtitle">Scope and comparison mode recalculate every network KPI and comment.</p></div><select class="table-search" id="network-period-select">${ctx.full.slice().reverse().map(x=>`<option value="${x.period}" ${x.period===ctx.raw?.period?"selected":""}>${x.period}</option>`).join("")}</select></div></section>
  <section class="kpi-grid">${kpiCard("passengers",fmtCompact(n(ctx.current.passengers)),fmtPct(pctChange(n(ctx.current.passengers),n(ctx.prior.passengers))),`${state.scope} · ${ctx.current.period}`,deltaTone(n(ctx.current.passengers)-n(ctx.prior.passengers)))}${kpiCard("asm",fmtCompact(n(ctx.current.asm)),fmtPct(pctChange(n(ctx.current.asm),n(ctx.prior.asm))),`${state.scope} capacity`,"neutral")}${kpiCard("load_factor",`${(100*n(ctx.current.load_factor)).toFixed(1)}%`,fmtPp(lfD),`${state.scope}`,deltaTone(lfD))}${kpiCard("departures",fmtCompact(n(ctx.current.departures_performed)),fmtPct(pctChange(n(ctx.current.departures_performed),n(ctx.prior.departures_performed))),`${state.scope}`,"neutral")}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Traffic and capacity</h2><p class="panel-subtitle">Passengers and available seats for ${esc(state.scope)}</p></div>${sourceChip("network")}</div><div class="chart-shell"><canvas id="network-trend"></canvas></div></article>${insightCard(networkCommentary(ctx.current,ctx.prior),"Network diagnosis")}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Top directional routes</h2><p class="panel-subtitle">Click a bar or row to inspect the exact route</p></div><span class="data-pill">Top ${shown.length}</span></div>${shown.length?`<div class="chart-shell route-chart"><canvas id="route-chart"></canvas></div>`:`<div class="empty-panel">No ranked routes are available for this scope yet.</div>`}</article>${insightCard(routeInsight(selected),"Selected route")}</section>
  ${shown.length?`<article class="panel flush"><div class="table-wrap"><table><thead><tr><th>Route</th><th>Scope</th><th>Passengers</th><th>Departures</th><th>Load factor</th></tr></thead><tbody>${shown.map(r=>`<tr class="selectable ${routeKey(r)===state.selectedRouteKey?"selected":""}" data-route-key="${esc(routeKey(r))}"><td>${esc(r.origin)}-${esc(r.destination)}</td><td>${esc(r.scope)}</td><td>${fmtCompact(n(r.passengers))}</td><td>${fmtInt(n(r.departures_performed))}</td><td>${r.load_factor==null?"n/a":`${(100*r.load_factor).toFixed(1)}%`}</td></tr>`).join("")}</tbody></table></div></article>`:""}`;
  makeChart("network-trend",{type:"line",data:{labels:ctx.visible.map(x=>x.period),datasets:[{label:"Passengers",data:ctx.visible.map(x=>x.passengers),borderColor:COLORS.blue,backgroundColor:COLORS.fill,fill:true,tension:.35,pointRadius:1},{label:"Seats",data:ctx.visible.map(x=>x.available_seats),borderColor:COLORS.muted,borderDash:[4,4],tension:.35,pointRadius:0}]},options:commonChartOptions({plugins:{legend:{display:true,labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}}})});
  if(shown.length){makeChart("route-chart",{type:"bar",data:{labels:shown.map(r=>`${r.origin}-${r.destination}`),datasets:[{data:shown.map(r=>r.passengers),backgroundColor:shown.map(r=>routeKey(r)===state.selectedRouteKey?COLORS.blue:"rgba(0,113,227,.20)"),borderRadius:8}]},options:{...commonChartOptions(),indexAxis:"y",interaction:{mode:"nearest",intersect:true},onClick:(evt,_els,chart)=>{const hits=chart.getElementsAtEventForMode(evt,"nearest",{intersect:true},true);if(!hits.length)return;const r=shown[hits[0].index];if(r){state.selectedRouteKey=routeKey(r);render();}}}});}
  document.getElementById("network-period-select")?.addEventListener("change",e=>{state.networkPeriod=e.target.value;render();});document.querySelectorAll("[data-route-key]").forEach(row=>row.addEventListener("click",()=>{state.selectedRouteKey=row.dataset.routeKey;render();}));
}

function renderFuel(){const ctx=fuelContext();if(!ctx.current||!ctx.prior)return renderUnavailable("No valid fuel comparison is available.");const c=ctx.current,p=ctx.prior;const costD=n(c.fuel_cost_usd)-n(p.fuel_cost_usd),gallonsD=n(c.fuel_gallons)-n(p.fuel_gallons),priceD=n(c.fuel_cost_per_gallon_usd)-n(p.fuel_cost_per_gallon_usd);const priceEffect=priceD*n(c.fuel_gallons),volumeEffect=gallonsD*n(p.fuel_cost_per_gallon_usd);
  dashboard.innerHTML=`<section class="filter-context panel"><div class="panel-header"><div><h2>Selected fuel month</h2><p class="panel-subtitle">Domestic / International changes both gallons and reported regional fuel cost, not just the label.</p></div><select class="table-search" id="fuel-period-select">${ctx.full.slice().reverse().map(x=>`<option value="${x.period}" ${x.period===ctx.raw?.period?"selected":""}>${x.period}</option>`).join("")}</select></div></section>
  <section class="kpi-grid">${kpiCard("fuel_cost",fmtUsdBn(n(c.fuel_cost_usd)/1e6),`${fmtUsdM(costD/1e6)} vs ${p.period}`,`${state.scope} · ${c.period}`,deltaTone(costD,false))}${kpiCard("fuel_gallons",fmtCompact(n(c.fuel_gallons)),fmtPct(pctChange(n(c.fuel_gallons),n(p.fuel_gallons))),state.scope,"neutral")}${kpiCard("fuel_price",fmtUsd(n(c.fuel_cost_per_gallon_usd)),`${priceD>=0?"+":"-"}${fmtUsd(Math.abs(priceD))}`,state.scope,deltaTone(priceD,false))}${kpiCard("load_factor",`${(100*n(networkContext().current?.load_factor)).toFixed(1)}%`,`network context`,state.scope,"neutral")}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Fuel trend</h2><p class="panel-subtitle">Reported cost and calculated cost per gallon</p></div>${sourceChip("fuel")}</div><div class="chart-shell tall"><canvas id="fuel-trend"></canvas></div></article>${insightCard(fuelCommentary(c,p),"Fuel variance analysis")}</section>
  <section class="equal-col"><article class="panel"><div class="panel-header"><div><h2>Price-volume bridge</h2><p class="panel-subtitle">Deterministic approximation using reported gallons and average unit cost</p></div></div><div class="metric-row"><span>Reported cost variance</span><strong class="${deltaTone(costD,false)}">${fmtUsdM(costD/1e6)}</strong><span>${fmtPct(pctChange(n(c.fuel_cost_usd),n(p.fuel_cost_usd)))}</span></div><div class="metric-row"><span>Approx. price effect</span><strong class="${deltaTone(priceEffect,false)}">${fmtUsdM(priceEffect/1e6)}</strong><span>unit price</span></div><div class="metric-row"><span>Approx. volume effect</span><strong class="${deltaTone(volumeEffect,false)}">${fmtUsdM(volumeEffect/1e6)}</strong><span>gallons</span></div></article><article class="panel"><div class="panel-header"><div><h2>Comment cell</h2><p class="panel-subtitle">Same context as the active filters</p></div></div><div class="comment-analysis large">${esc(fuelCommentary(c,p).body)} ${esc(fuelCommentary(c,p).bullets.join(" "))}</div></article></section>`;
  makeChart("fuel-trend",{type:"bar",data:{labels:ctx.visible.map(x=>x.period),datasets:[{label:"Fuel cost $m",data:ctx.visible.map(x=>n(x.fuel_cost_usd)/1e6),backgroundColor:"rgba(0,113,227,.20)",borderRadius:7,yAxisID:"y"},{type:"line",label:"$/gal",data:ctx.visible.map(x=>x.fuel_cost_per_gallon_usd),borderColor:COLORS.dark,pointRadius:2,tension:.35,yAxisID:"y1"}]},options:commonChartOptions({plugins:{legend:{display:true,labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}},scales:{x:{grid:{display:false}},y:{grid:{color:COLORS.line},ticks:{callback:v=>`$${v}m`}},y1:{position:"right",grid:{display:false},ticks:{callback:v=>`$${v}`}}}})});document.getElementById("fuel-period-select")?.addEventListener("change",e=>{state.fuelPeriod=e.target.value;render();});
}

function aircraftEconomics(type){return(bts?.p52_aircraft_economics?.latest_aircraft_type_economics||[]).find(r=>String(r.aircraft_type)===String(type))||null;}
function renderFleet(){const fleet=bts?.b43_fleet;if(!fleet)return renderUnavailable("Fleet inventory is unavailable.");const aircraft=fleet.aircraft||[];const q=state.fleetQuery.trim().toLowerCase();const filtered=q?aircraft.filter(a=>[a.tail_number,a.model,a.manufacturer,a.aircraft_type].some(v=>String(v||"").toLowerCase().includes(q))):aircraft;let selected=filtered.find(a=>a.tail_number===state.selectedFleetTail)||filtered[0]||null;if(selected&&!state.selectedFleetTail)state.selectedFleetTail=selected.tail_number;const econ=selected?aircraftEconomics(selected.aircraft_type):null;const old=aircraft.filter(a=>a.manufacture_year&&fleet.inventory_year-a.manufacture_year>=20).length;const ageBins=[0,0,0,0,0];aircraft.forEach(a=>{if(!a.manufacture_year)return;const age=fleet.inventory_year-a.manufacture_year;if(age<5)ageBins[0]++;else if(age<10)ageBins[1]++;else if(age<15)ageBins[2]++;else if(age<20)ageBins[3]++;else ageBins[4]++;});const manufacturer={};(fleet.model_mix||[]).forEach(x=>{const m=cleanManufacturer(x.manufacturer);manufacturer[m]=(manufacturer[m]||0)+n(x.aircraft_count);});const mix=Object.entries(manufacturer).sort((a,b)=>b[1]-a[1]);
  dashboard.innerHTML=`<section class="kpi-grid">${kpiCard("active_aircraft",fmtInt(n(fleet.active_aircraft_count)),`inventory ${fleet.inventory_year}`,"tail-level", "neutral")}${kpiCard("fleet_age",`${n(fleet.average_age_years).toFixed(1)} yrs`,`${old} aircraft at 20+ years`,"active inventory","neutral")}${kpiCard("aircraft_cost_hour",econ&&n(econ.air_hours)?fmtUsd(n(econ.aircraft_operating_expense_source)/n(econ.air_hours),0):"select aircraft",selected?.model||"","P-5.2 aircraft type","neutral")}${kpiCard("seats",selected?fmtInt(n(selected.number_of_seats)):"n/a",selected?.tail_number||"selected aircraft","B-43","neutral")}</section>
  <section class="two-col"><article class="panel"><div class="panel-header"><div><h2>Fleet composition</h2><p class="panel-subtitle">Active aircraft by manufacturer</p></div>${sourceChip("fleet")}</div><div class="chart-shell"><canvas id="fleet-mix"></canvas></div></article><article class="panel"><div class="panel-header"><div><h2>Fleet age profile</h2><p class="panel-subtitle">Age buckets based on manufacture year</p></div></div><div class="chart-shell"><canvas id="fleet-age"></canvas></div></article></section>
  <section class="equal-col"><article class="panel fleet-detail"><div class="hero-label">Selected aircraft</div><div class="detail-title">${esc(selected?.tail_number||"No match")}</div><div class="detail-subtitle">${selected?`${esc(cleanManufacturer(selected.manufacturer))} ${esc(selected.model)} · type ${esc(selected.aircraft_type)}`:""}</div>${selected?`<div class="detail-grid"><div class="detail-metric"><span>Year</span><strong>${selected.manufacture_year||"n/a"}</strong></div><div class="detail-metric"><span>Seats</span><strong>${fmtInt(n(selected.number_of_seats))}</strong></div><div class="detail-metric"><span>Payload lb</span><strong>${fmtInt(n(selected.capacity_in_pounds))}</strong></div><div class="detail-metric"><span>Cost / air hour ${metricHelp("aircraft_cost_hour")}</span><strong>${econ&&n(econ.air_hours)?fmtUsd(n(econ.aircraft_operating_expense_source)/n(econ.air_hours),0):"n/a"}</strong></div></div>`:""}</article><article class="panel"><div class="panel-header"><div><h2>What this means</h2><p class="panel-subtitle">Fleet age is a trade-off, not automatically bad.</p></div>${sourceChip("aircraft")}</div><p class="explain-copy">Older aircraft can raise maintenance burden and fuel inefficiency, but they may carry lower ownership cost. P-5.2 lets you inspect aircraft-type economics instead of assuming “newer is always better.”</p></article></section>
  <article class="panel flush"><div class="panel-header table-head"><div><h2>Aircraft inventory</h2><p class="panel-subtitle">Search by tail, model, manufacturer or aircraft type.</p></div><input class="table-search" id="fleet-search" type="search" value="${esc(state.fleetQuery)}" placeholder="Search fleet"></div><div class="table-wrap fleet-table"><table><thead><tr><th>Tail</th><th>Manufacturer</th><th>Model</th><th>Year</th><th>Seats</th><th>Type</th></tr></thead><tbody>${filtered.slice(0,180).map(a=>`<tr class="selectable ${a.tail_number===state.selectedFleetTail?"selected":""}" data-tail="${esc(a.tail_number)}"><td>${esc(a.tail_number)}</td><td>${esc(cleanManufacturer(a.manufacturer))}</td><td>${esc(a.model)}</td><td>${a.manufacture_year||"n/a"}</td><td>${fmtInt(n(a.number_of_seats))}</td><td>${esc(a.aircraft_type)}</td></tr>`).join("")}</tbody></table></div></article>`;
  makeChart("fleet-mix",{type:"doughnut",data:{labels:mix.map(x=>x[0]),datasets:[{data:mix.map(x=>x[1]),backgroundColor:[COLORS.blue,"#5aa5ef","#8fc1f2","#b8d8f6","#d5e8fa",COLORS.muted],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:"68%",plugins:{legend:{position:"bottom",labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}}}});makeChart("fleet-age",{type:"bar",data:{labels:["<5","5-9","10-14","15-19","20+"],datasets:[{data:ageBins,backgroundColor:["rgba(0,113,227,.18)","rgba(0,113,227,.24)","rgba(0,113,227,.32)","rgba(180,95,6,.26)","rgba(215,0,21,.22)"],borderRadius:7}]},options:commonChartOptions()});document.getElementById("fleet-search")?.addEventListener("input",e=>{state.fleetQuery=e.target.value;clearTimeout(window.__fleetTimer);window.__fleetTimer=setTimeout(render,160);});document.querySelectorAll("[data-tail]").forEach(r=>r.addEventListener("click",()=>{state.selectedFleetTail=r.dataset.tail;render();}));
}

const VARIANCE_DEFS={financial:{label:"Financials",cadence:"quarterly",data:()=>bts?.p12_financials||[],metrics:{operating_revenue_usd_m:["Operating revenue","operating_revenue",true],operating_expense_usd_m:["Operating expense","operating_expense",false],operating_profit_loss_usd_m:["Operating profit","operating_profit",true],passenger_revenue_usd_m:["Passenger revenue","passenger_revenue",true],maintenance_expense_usd_m:["Maintenance","maintenance",false]}},network:{label:"Network",cadence:"monthly",data:()=> (bts?.t100_network?.history||[]).map(scopedNetworkRow),metrics:{passengers:["Passengers","passengers",true],asm:["ASM","asm",true],rpm:["RPM","rpm",true],departures_performed:["Departures","departures",true],load_factor:["Load factor","load_factor",true]}},fuel:{label:"Fuel",cadence:"monthly",data:()=> (bts?.p12a_fuel||[]).map(scopedFuelRow),metrics:{fuel_cost_usd:["Fuel cost","fuel_cost",false],fuel_gallons:["Fuel gallons","fuel_gallons",false],fuel_cost_per_gallon_usd:["Fuel cost / gallon","fuel_price",false]}}};
function varianceValue(v,key){if(key.includes("usd_m"))return fmtUsdM(v);if(key==="fuel_cost_usd")return fmtUsdM(v/1e6);if(key==="fuel_cost_per_gallon_usd")return fmtUsd(v);if(key==="load_factor")return`${(100*n(v)).toFixed(1)}%`;return fmtCompact(v);}
function varianceComment(dataset,key,c,p){if(dataset==="financial")return financialMetricComment(key,c,p);if(dataset==="network"){const all=networkCommentary(c,p);return `${all.body} ${all.bullets[0]||""}`;}const all=fuelCommentary(c,p);return `${all.body} ${all.bullets.join(" ")}`;}
function contextForVariance(dataset,period){if(dataset==="financial"){state.financialPeriod=period;return financialContext();}if(dataset==="network"){state.networkPeriod=period;return networkContext();}state.fuelPeriod=period;return fuelContext();}
function renderVariance(){const def=VARIANCE_DEFS[state.varianceDataset]||VARIANCE_DEFS.financial;const raw=def.data();if(!raw.length)return renderUnavailable("No variance data is available.");if(!def.metrics[state.varianceMetric])state.varianceMetric=Object.keys(def.metrics)[0];if(!state.variancePeriod||!raw.some(x=>x.period===state.variancePeriod))state.variancePeriod=raw.at(-1).period;const ctx=contextForVariance(state.varianceDataset,state.variancePeriod);const c=ctx.current,p=ctx.prior;if(!c||!p)return renderUnavailable("Choose a period with a valid comparator.");const [label,mkey,fav]=def.metrics[state.varianceMetric];const cv=n(c[state.varianceMetric]),pv=n(p[state.varianceMetric]),d=cv-pv;const rows=Object.entries(def.metrics).map(([key,[lab,mk,f]])=>({key,label:lab,mkey:mk,fav:f,c:n(c[key]),p:n(p[key])}));
  dashboard.innerHTML=`<section class="panel"><div class="panel-header"><div><h2>Build a variance</h2><p class="panel-subtitle">All comments use the active scope and comparison mode.</p></div></div><div class="variance-controls"><label>Dataset<select id="var-dataset">${Object.entries(VARIANCE_DEFS).map(([k,x])=>`<option value="${k}" ${k===state.varianceDataset?"selected":""}>${x.label}</option>`).join("")}</select></label><label>Metric<select id="var-metric">${Object.entries(def.metrics).map(([k,x])=>`<option value="${k}" ${k===state.varianceMetric?"selected":""}>${x[0]}</option>`).join("")}</select></label><label>Period<select id="var-period">${raw.slice().reverse().map(x=>`<option value="${x.period}" ${x.period===state.variancePeriod?"selected":""}>${x.period}</option>`).join("")}</select></label></div></section>
  <section class="hero-grid"><article class="hero-card"><div class="hero-label">${metricTitle(mkey,label)}</div><div class="hero-value">${varianceValue(d,state.varianceMetric)}</div><div class="hero-delta ${deltaTone(d,fav)}">${fmtPct(pctChange(cv,pv))} vs ${esc(p.period)}</div><p class="hero-copy">Current ${esc(c.period)}: ${varianceValue(cv,state.varianceMetric)}. Comparator ${esc(p.period)}: ${varianceValue(pv,state.varianceMetric)}.</p></article>${insightCard({headline:`${label}: what is driving the movement`,body:varianceComment(state.varianceDataset,state.varianceMetric,c,p),bullets:[`Network scope: ${state.scope}.`,`Comparison: ${compareModeLabel()}.`]},"Variance diagnosis")}</section>
  <article class="panel flush"><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Current</th><th>Comparator</th><th>Variance</th><th>Variance %</th><th class="comment-col">Analysis</th></tr></thead><tbody>${rows.map(r=>{const dd=r.c-r.p;return`<tr><td>${metricTitle(r.mkey,r.label)}</td><td>${varianceValue(r.c,r.key)}</td><td>${varianceValue(r.p,r.key)}</td><td class="${deltaTone(dd,r.fav)}">${varianceValue(dd,r.key)}</td><td class="${deltaTone(dd,r.fav)}">${fmtPct(pctChange(r.c,r.p))}</td><td class="comment-analysis">${esc(varianceComment(state.varianceDataset,r.key,c,p))}</td></tr>`;}).join("")}</tbody></table></div></article>`;
  document.getElementById("var-dataset")?.addEventListener("change",e=>{state.varianceDataset=e.target.value;state.varianceMetric=Object.keys(VARIANCE_DEFS[state.varianceDataset].metrics)[0];state.variancePeriod=null;render();});document.getElementById("var-metric")?.addEventListener("change",e=>{state.varianceMetric=e.target.value;render();});document.getElementById("var-period")?.addEventListener("change",e=>{state.variancePeriod=e.target.value;render();});
}

function renderGlossary(){const q=state.glossaryQuery.trim().toLowerCase();const entries=Object.entries(METRICS).filter(([,m])=>!q||[m.label,m.category,m.definition,m.formula,m.source].join(" ").toLowerCase().includes(q));const grouped={};entries.forEach(([k,m])=>(grouped[m.category]??=[]).push([k,m]));currentInsight="The glossary explains every specialist metric and every BTS schedule used by the dashboard in plain English.";dashboard.innerHTML=`<section class="journey-hero"><h2>Airline finance without the alphabet soup.</h2><p>Hover or focus the question mark beside any KPI anywhere in the dashboard for a short explanation. This page gives the full definition, formula and source.</p><input class="glossary-search" id="glossary-search" type="search" value="${esc(state.glossaryQuery)}" placeholder="Search margin, ASM, fuel, CASM..."></section>${Object.entries(grouped).map(([cat,items])=>`<section class="panel"><div class="panel-header"><div><h2>${esc(cat)}</h2><p class="panel-subtitle">${items.length} metrics</p></div></div><div class="glossary-grid">${items.map(([k,m])=>`<article class="glossary-card"><h3>${esc(m.label)} ${metricHelp(k)}</h3><p>${esc(m.definition)}</p><div><strong>Formula</strong><span>${esc(m.formula)}</span></div><div><strong>Source</strong><span>${esc(m.source)}</span></div></article>`).join("")}</div></section>`).join("")}<section class="panel"><div class="panel-header"><div><h2>What are P-1.2, P-5.2 and the other BTS codes?</h2><p class="panel-subtitle">They are government reporting schedule names, not metrics.</p></div></div><div class="source-guide">${SOURCES.map(([name,code,desc])=>`<article><div class="source-code">${esc(code)}</div><div><h3>${esc(name)}</h3><p>${esc(desc)}</p></div></article>`).join("")}</div></section>`;document.getElementById("glossary-search")?.addEventListener("input",e=>{state.glossaryQuery=e.target.value;clearTimeout(window.__glossTimer);window.__glossTimer=setTimeout(render,120);});}

const FLOW=[["Collect","Official Delta IR and U.S. DOT BTS TranStats are the only sources. No private airline systems or customer data."],["Filter","Huge government files are filtered to Delta and the retained periods needed for analysis."],["Validate","Automated tests check airline identity, period coverage, schemas and financial consistency."],["Model","The pipeline converts raw schedules into finance, fuel, network, route and fleet metrics."],["Publish","Only compact analytical JSON is stored in GitHub Pages; raw downloads remain temporary."]];
function renderJourney(){const step=FLOW[state.flowStep]||FLOW[0],generated=bts?.metadata?.generated_at_utc?new Date(bts.metadata.generated_at_utc):null;currentInsight="The pipeline keeps raw public downloads temporary and publishes only compact Delta analytical outputs after automated validation.";dashboard.innerHTML=`<section class="journey-hero"><h2>From public filings to an explorable management view.</h2><p>The objective is simple: collect official public data, keep only what the analysis needs, check it, calculate finance-friendly metrics and publish a small auditable output.</p></section><section class="flow-diagram panel"><div class="panel-header"><div><h2>Information flow</h2><p class="panel-subtitle">Click a step for a plain-English explanation.</p></div><span class="data-pill live">Automated</span></div><div class="flow-track">${FLOW.map(([a,b],i)=>`<article class="flow-step ${i===state.flowStep?"active":""}" data-flow="${i}"><div class="flow-number">0${i+1}</div><h3>${esc(a)}</h3><p>${esc(b.split(".")[0])}.</p></article>`).join("")}</div><div class="flow-explainer"><strong>${esc(step[0])}</strong><span>${esc(step[1])}</span></div></section><section class="residency-grid"><article class="residency-card"><div class="hero-label">Raw data residency</div><h3>Temporary</h3><p>The large source ZIP/CSV files are downloaded inside the GitHub Actions runner and are not committed to the public repository.</p></article><article class="residency-card"><div class="hero-label">Published data</div><h3>Compact JSON</h3><p>GitHub stores only filtered, aggregated analytical outputs required by the dashboard.</p></article><article class="residency-card"><div class="hero-label">Personal data</div><h3>None</h3><p>The project uses airline-level public reporting and contains no customer or employee personal information.</p></article></section><section class="panel"><div class="panel-header"><div><h2>Data freshness</h2><p class="panel-subtitle">Different official datasets publish at different speeds.</p></div></div><div class="source-guide"><article><div class="source-code">Latest</div><div><h3>Delta Investor Relations</h3><p>Used for the newest management financial result and unit-economics KPIs.</p></div></article><article><div class="source-code">Monthly</div><div><h3>BTS network and fuel</h3><p>T-100 and P-12(a) provide detailed monthly operating history after the government release lag.</p></div></article><article><div class="source-code">Quarterly</div><div><h3>BTS financials</h3><p>P-1.2 and P-5.2 provide the deeper historical finance and aircraft-economics layer.</p></div></article><article><div class="source-code">Annual</div><div><h3>BTS fleet inventory</h3><p>B-43 is an annual aircraft inventory snapshot.</p></div></article></div><div class="notice">Last compact BTS build: ${generated?generated.toLocaleString():"not available"}. The scheduled refresh runs monthly and only publishes after validation passes.</div></section>`;document.querySelectorAll("[data-flow]").forEach(x=>x.addEventListener("click",()=>{state.flowStep=+x.dataset.flow;render();}));}

function renderUnavailable(msg){dashboard.innerHTML=`<div class="panel empty-panel">${esc(msg)}</div>`;}
function updateMeta(){const [t,s]=PAGE_META[state.view]||PAGE_META.overview;titleEl.textContent=t;subtitleEl.textContent=s;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===state.view));}
function updateControls(){document.getElementById("range-select").value=String(state.range);document.getElementById("scope-select").value=state.scope;document.getElementById("compare-select").value=state.compare;document.getElementById("focus-select").value=state.focus;}
function syncHash(){const p=new URLSearchParams({view:state.view,range:String(state.range),scope:state.scope,compare:state.compare,focus:state.focus});history.replaceState(null,"",`#${p}`);}
function readHash(){const p=new URLSearchParams(location.hash.replace(/^#/,""));if(PAGE_META[p.get("view")])state.view=p.get("view");if([6,12,24].includes(+p.get("range")))state.range=+p.get("range");if(["all","domestic","international"].includes(p.get("scope")))state.scope=p.get("scope");if(["yoy","prior","ytd"].includes(p.get("compare")))state.compare=p.get("compare");if(p.get("focus"))state.focus=p.get("focus");}
function render(){destroyCharts();updateMeta();updateControls();syncHash();const fn={overview:renderOverview,financials:renderFinancials,network:renderNetwork,fuel:renderFuel,fleet:renderFleet,variance:renderVariance,glossary:renderGlossary,journey:renderJourney}[state.view]||renderOverview;fn();}
function setView(v){if(!PAGE_META[v])return;state.view=v;sidebar?.classList.remove("open");render();window.scrollTo({top:0,behavior:"smooth"});}
function toast(msg){const el=document.getElementById("toast");if(!el)return;el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),1800);}

async function init(){readHash();try{[actuals,bts]=await Promise.all([fetch("data/actuals.json",{cache:"no-store"}).then(r=>r.json()),fetch("data/bts_summary.json",{cache:"no-store"}).then(r=>r.json())]);if(window.Chart){Chart.defaults.font.family='-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",Arial,sans-serif';Chart.defaults.color="#6e6e73";}freshnessEl.textContent="Official data loaded";freshnessEl.classList.add("ready");footerRefreshEl.textContent=bts?.metadata?.generated_at_utc?`BTS build ${new Date(bts.metadata.generated_at_utc).toLocaleDateString()}`:"";render();}catch(err){console.error(err);freshnessEl.textContent="Data load failed";dashboard.innerHTML=`<div class="panel empty-panel">The published analytical JSON could not be loaded.</div>`;}}

document.querySelectorAll(".nav-item").forEach(x=>x.addEventListener("click",()=>setView(x.dataset.view)));
document.getElementById("range-select")?.addEventListener("change",e=>{state.range=+e.target.value;state.selectedRouteKey=null;render();});
document.getElementById("scope-select")?.addEventListener("change",e=>{state.scope=e.target.value;state.selectedRouteKey=null;render();});
document.getElementById("compare-select")?.addEventListener("change",e=>{state.compare=e.target.value;state.financialPeriod=null;state.networkPeriod=null;state.fuelPeriod=null;state.variancePeriod=null;render();});
document.getElementById("focus-select")?.addEventListener("change",e=>{state.focus=e.target.value;render();});
document.getElementById("reset-filters-button")?.addEventListener("click",()=>{Object.assign(state,{range:12,scope:"all",compare:"yoy",focus:"operating_margin",financialPeriod:null,networkPeriod:null,fuelPeriod:null,selectedRouteKey:null,variancePeriod:null});render();toast("Filters reset");});
document.getElementById("copy-insight-button")?.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(currentInsight||"No insight generated yet.");toast("Insight copied");}catch(_){toast("Copy not available");}});
document.getElementById("mobile-nav-button")?.addEventListener("click",()=>sidebar?.classList.toggle("open"));
document.querySelectorAll("[data-shortcut]").forEach(x=>x.addEventListener("click",()=>{const m={margin:"financials",network:"network",fuel:"fuel",fleet:"fleet"};setView(m[x.dataset.shortcut]||"overview");}));
window.addEventListener("hashchange",()=>{readHash();render();});
init();